import java.lang.reflect.*;import com.koios.GameService;import com.koios.game.arpg.*;import com.koios.game.model.player.Player;
/** Fixture commands must never grant progression or items to ordinary or online accounts. */
public final class QaFixtureCheck {
 static int checks;static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
 static Player fixture(String name,int index){Player p=PrototypeIntegrationCheck.player(name,index);p.allowSaveRequests=false;PrototypeIntegrationCheck.idle(p);return p;}
 static void unchanged(Player p,String command){long xp=p.getArpgProgress().xp();int size=p.getInventory().size(),coins=p.getInventory().getCount(995);int[] materials=new int[CraftingCurrency.IDS.length];for(int i=0;i<materials.length;i++)materials[i]=p.getInventory().getCount(CraftingCurrency.IDS[i]);check(QaFixtures.handle(p,command),"QA-prefixed command consumed safely");check(p.getArpgProgress().xp()==xp&&p.getInventory().size()==size&&p.getInventory().getCount(995)==coins,"Rejected fixture command grants nothing: "+command);for(int i=0;i<materials.length;i++)check(p.getInventory().getCount(CraftingCurrency.IDS[i])==materials[i],"Rejected fixture command preserves material quantities");}
 public static void main(String[] args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=fixture("qatests",50);check(!QaFixtures.handle(p,"hello"),"Unrelated commands fall through");for(String cmd:new String[]{"arpgqa level bad","arpgqa level 0","arpgqa level 31","arpgqa level","arpgqa base 1","arpgqa base notanid","arpgqa unknown","arpgqa gems extra","arpgqa materials extra"})unchanged(p,cmd);
 for(String name:new String[]{"Max1","qa","qaab","qa_bad","qaabcdefghijkl"})for(String command:new String[]{"arpgqa gems","arpgqa materials"})unchanged(fixture(name,51),command);p.setTeleporting(true);unchanged(p,"arpgqa gems");unchanged(p,"arpgqa materials");p.setTeleporting(false);p.setDead(true);unchanged(p,"arpgqa gems");unchanged(p,"arpgqa materials");p.setDead(false);p.setIsTrading(true);unchanged(p,"arpgqa gems");unchanged(p,"arpgqa materials");p.setIsTrading(false);p.getBankField().setBanking(true);unchanged(p,"arpgqa materials");p.getBankField().setBanking(false);
 Field singleton=GameService.class.getDeclaredField("singleton");singleton.setAccessible(true);Object service=singleton.get(null);Field online=GameService.class.getDeclaredField("onlineMode");online.setAccessible(true);boolean was=online.getBoolean(service);try{online.setBoolean(service,true);unchanged(p,"arpgqa level 20");unchanged(p,"arpgqa base 22430");unchanged(p,"arpgqa gems");unchanged(p,"arpgqa materials");}finally{online.setBoolean(service,was);}
 QaFixtures.handle(p,"arpgqa level 15");check(p.getArpgProgress().level()==15,"Offline QA can set an exact legitimate progression level");long xp=p.getArpgProgress().xp();QaFixtures.handle(p,"arpgqa level 5");check(p.getArpgProgress().xp()==xp,"Lower target does not reduce progress");QaFixtures.handle(p,"arpgqa base 22430");check(p.getInventory().getCount(22430)==1,"Valid base request grants exact selected base");int before=p.getInventory().size();QaFixtures.handle(p,"arpgqa gems");check(p.getInventory().size()==before+4&&p.getInventory().getCount(995)==100,"Gem setup grants two active gems, support gem and coins");int active=0,support=0;for(int s=0;s<28;s++)if(MapRuns.isGem(p.getInventory().get(s))){if(p.getInventory().get(s).getRoll().getGem().support)support++;else active++;}check(active==2&&support==1,"Actual setup gem categories correct");check(CraftingCurrency.IDS.length==11,"QA exercises all eleven current currency types");QaFixtures.handle(p,"arpgqa materials");for(int id:CraftingCurrency.IDS)check(p.getInventory().getCount(id)==5,"QA grants exactly five of material "+id);QaFixtures.handle(p,"arpgqa materials");for(int id:CraftingCurrency.IDS)check(p.getInventory().getCount(id)==10,"Repeated QA setup adds a predictable five-stack");p.setTeleporting(true);unchanged(p,"arpgqa materials");p.setTeleporting(false);System.out.println("Passed "+checks+" local QA fixture guard/setup checks.");}
}
